    public static bool operator==(Vector3 a,Vector3 b){return a.x==b.x&&a.y==b.y&&a.z==b.z;} public static bool operator!=(Vector3 a,Vector3 b){return !(a==b);} public override bool Equals(object o){return o is Vector3 && (Vector3)o==this;} public override int GetHashCode(){return x.GetHashCode()^y.GetHashCode()^z.GetHashCode();}
