    public static Vector3 Lerp(Vector3 a,Vector3 b,float t){t=Mathf.Clamp01(t); return a+(b-a)*t;} public static Vector3 Slerp(Vector3 a,Vector3 b,float t){return Lerp(a,b,t).normalized*Mathf.Lerp(a.magnitude,b.magnitude,t);}
    public static float Dot(Vector3 a,Vector3 b){return a.x*b.x+a.y*b.y+a.z*b.z;} public static Vector3 Cross(Vector3 a,Vector3 b){return new Vector3(a.y*b.z-a.z*b.y,a.z*b.x-a.x*b.z,a.x*b.y-a.y*b.x);} public static float Distance(Vector3 a,Vector3 b){return (a-b).magnitude;}
