    public static float Repeat(float t,float l){return t-(float)Math.Floor(t/l)*l;} public static float PingPong(float t,float l){t=Repeat(t,l*2); return l-Math.Abs(t-l);} public static int RoundToInt(float f){return (int)Math.Round(f, MidpointRounding.ToEven);} public static int CeilToInt(float f){return (int)Math.Ceiling(f);} public static int FloorToInt(float f){return (int)Math.Floor(f);} public static float Floor(float f){return (float)Math.Floor(f);} public static float Round(float f){return (float)Math.Round(f);} public static float Ceil(float f){return (float)Math.Ceiling(f);} public static bool Approximately(float a,float b){return Math.Abs(a-b)<1e-6f;} public static float Sign(float f){return f>=0?1:-1;} public static float Pow(float a,float b){return (float)Math.Pow(a,b);} public static float SmoothStep(float a,float b,float t){t=Clamp01(t); t=t*t*(3-2*t); return a+(b-a)*t;} public static float MoveTowards(float c,float t,float d){return Math.Abs(t-c)<=d? t : c+Math.Sign(t-c)*d;} public static float DeltaAngle(float a,float b){float d=Repeat(b-a,360); if(d>180)d-=360; return d;} public static float MoveTowardsAngle(float c,float t,float d){float delta=DeltaAngle(c,t); return Math.Abs(delta)<=d? t : c+Math.Sign(delta)*d;} }
